import * as THREE from 'three/webgpu';

export default function createNode(config, ctx) {
  // Aspect ratio from atlas region: 512 / 320 = 1.6
  const aspectRatio = 512 / 320;
  const geometry = new THREE.PlaneGeometry(aspectRatio, 1);

  // Load ceramic grain texture
  const textureMap = ctx.textureLoader.load(
    '/prism-assets/chrome/ceramic-grain.map.png'
  );
  textureMap.magFilter = THREE.LinearFilter;
  textureMap.minFilter = THREE.LinearMipMapLinearFilter;

  // Create material with texture
  const material = new THREE.MeshBasicNodeMaterial({
    map: textureMap,
    transparent: true,
    side: THREE.DoubleSide,
  });

  // Create mesh
  const mesh = new THREE.Mesh(geometry, material);

  // Apply scene placement as specified
  mesh.position.set(3.2, -0.3, 0);
  mesh.rotation.set(0, 0, 0);
  mesh.scale.set(1, 1, 1);

  // Setup cleanup
  mesh.userData.cleanup = () => {
    geometry.dispose();
    material.dispose();
    textureMap.dispose();
  };

  mesh.userData.handlers = {};

  return mesh;
}
